package pzvrphysicality;
import java.util.*;import local.pzvr.*;import zombie.characters.IsoPlayer;import zombie.inventory.InventoryItem;import zombie.inventory.types.InventoryContainer;import zombie.scripting.objects.ItemBodyLocation;import zombie.scripting.objects.ItemTag;

/** Real owned bag identities and original action intents. Suspension is a detached preview pose only. */
public final class BackpackContents {
 public record Selection(IsoPlayer actor,InventoryContainer bag,int side,long epoch,int page,int pages,int count,List<InventoryItem> items,BackpackCapture.Prepared suspension){public Selection{items=Collections.unmodifiableList(new ArrayList<>(items));}}
 public record Request(int kind,int side,int bagSide,IsoPlayer actor,InventoryContainer bag,InventoryItem item,InventoryItem other,long ticket,long epoch,long rigGeneration,long created,int page,int cell,int id,String type,int count,int uses,List<BackpackCapture.Part> bagGeometry,List<BackpackCapture.Part> itemGeometry,BackpackCapture.Prepared frozen){public Request{bagGeometry=List.copyOf(bagGeometry);itemGeometry=List.copyOf(itemGeometry);}}
 private static final BackpackPolicy policy=new BackpackPolicy();private static final BackpackGesture gesture=new BackpackGesture();private static final BackpackLayout<InventoryItem> layout=new BackpackLayout<>();
 private static volatile boolean enabled;private static double reach=.075;private static IsoPlayer actor;private static InventoryContainer bag;private static int bagSide=-1,page;private static long epoch=1,sequence,rigGeneration=-1,nextScan;private static Request pending,active;private static BackpackCapture.Prepared suspension;private static String status="Physical backpack contents Off";
 private static IsoPlayer player(){return IsoPlayer.players.length==0?null:IsoPlayer.players[0];}
 private static boolean supported(InventoryItem item){return item!=null&&!item.isForceDropHeavyItem()&&!item.isRequiresEquippedBothHands()&&!item.hasTag(ItemTag.REPLACE_PRIMARY)&&item.getCount()==1&&item.getCurrentUses()>0;}
 public static boolean transferable(InventoryItem item){return supported(item)&&!(item instanceof InventoryContainer);}
 private static boolean wearable(InventoryItem item){return item instanceof InventoryContainer value&&supported(item)&&!item.isBroken()&&value.canBeEquipped()==ItemBodyLocation.BACK;}
 private static boolean ownedBag(IsoPlayer p,InventoryContainer value){return p!=null&&value!=null&&wearable(value)&&value.getContainer()==p.getInventory()&&p.getInventory().contains(value)&&value.getWorldItem()==null&&value.getItemContainer()!=null&&value.getItemContainer().getContainingItem()==value&&p.getClothingItem_Back()!=value;}
 private static boolean unheld(IsoPlayer p,InventoryContainer value){return ownedBag(p,value)&&NativeItems.hand(p,0)!=value&&NativeItems.hand(p,1)!=value;}
 private static boolean ownedAt(IsoPlayer p,InventoryContainer value,int side){return side<0?unheld(p,value):ownedBag(p,value)&&NativeItems.hand(p,side)==value&&NativeItems.hand(p,1-side)!=value;}
 private static boolean ownAction(IsoPlayer p,long ticket){if(!p.hasTimedActions())return true;var actions=p.getCharacterActions();if(actions==null||actions.isEmpty()||!(actions.getFirst() instanceof zombie.characters.CharacterTimedActions.LuaTimedActionNew action)||action.getTable()==null)return false;Object t=action.getTable().rawget("pzvrBackpackTicket");return t instanceof Number n&&n.doubleValue()==ticket;}
 private static boolean traceEligible(IsoPlayer p){var input=Engine.latestInput;long now=System.nanoTime();return enabled&&Main.ready()&&p!=null&&p==player()&&!p.isDead()&&p.getVehicle()==null&&p.getSquare()!=null&&(p.getClothingItem_Back()==null||!p.getClothingItem_Back().hasTag(ItemTag.REPLACE_PRIMARY))&&Engine.active()&&Engine.worldPresent&&!zombie.network.GameClient.client&&!zombie.network.GameServer.server&&!zombie.GameTime.isGamePaused()&&!VrApi.fullHud()&&!VrApi.pointerActive()&&!zombie.ui.UIManager.isModalVisible()&&!zombie.core.Core.getInstance().isDoingTextEntry()&&input!=null&&input.focused()&&input.head()!=null&&PzvrContacts.sample(now)!=null;}
 private static boolean eligible(IsoPlayer p){return traceEligible(p)&&(active!=null?ownAction(p,active.ticket):!p.hasTimedActions()&&NativeItems.supportsPhysicalGestures(p));}
 private static boolean prior(int side){return NativeBody.ownsGrip(side)||NativeBody.request()!=null||NativeCurtains.busy()||NativeCurtains.reservesGrip(side)||NativeItems.request()!=null||NativeConsumption.request()!=null||NativeConsumption.bite()!=null||NativeTaps.busy()||NativeCrafting.request()!=null;}
 private static void reset(){pending=active=null;suspension=null;actor=null;bag=null;bagSide=-1;page=0;layout.clear();nextScan=0;rigGeneration=-1;epoch++;gesture.reset();policy.reset();BackpackCapture.clear();}
 public static synchronized void configure(boolean value,double reachCm){if(!Double.isFinite(reachCm)||reachCm<3||reachCm>12)throw new IllegalArgumentException("Backpack contact reach");if(value&&!Main.ready())throw new IllegalStateException("SDK validation pending");enabled=value;reach=reachCm/100;reset();WorldRigCapture.requestBackpack(value);status=value?"Hold a native backpack forward; release grips before reaching for its contents":"Physical backpack contents Off";}
 public static boolean enabled(){return enabled;}
 private static boolean suspendedValid(){var rig=WorldRigCapture.latest;return suspension!=null&&suspension.actor().get()==actor&&suspension.bag().get()==bag&&unheld(actor,bag)&&traceEligible(actor)&&rig!=null&&rig.actor()==actor&&rig.fresh(System.nanoTime())&&rig.generation()==suspension.rigGeneration()&&BackpackCapture.current(suspension.parts())&&rig.mouth().distance(new ContactFrame.Point(suspension.pose()[0],suspension.pose()[1],suspension.pose()[2]))<2.5*suspension.basis().units();}
 public static synchronized boolean context(IsoPlayer p,InventoryContainer value,int side,long generation){return generation==epoch&&p==actor&&value==bag&&side==bagSide&&eligible(p)&&ownedAt(p,value,side)&&(side>=0||suspendedValid());}
 private static void scan(){var items=bag.getItemContainer().getItems();if(items.size()>BackpackLayout.MAX_ITEMS)throw new IllegalArgumentException("More than 2048 bag entries; use native inventory");var ordered=new ArrayList<InventoryItem>();var ids=new HashSet<Integer>();for(var item:items){if(item==null||item.getContainer()!=bag.getItemContainer()||item.getWorldItem()!=null||!ids.add(item.getID()))throw new IllegalArgumentException("Native backpack item identity");ordered.add(item);}ordered.sort(Comparator.comparingInt(InventoryItem::getID));layout.reconcile(ordered);if(page>=layout.pages()){page=layout.pages()-1;epoch++;pending=active=null;policy.reset();gesture.reset();BackpackCapture.clear();}}
 private static boolean identify(){var p=player();if(active!=null&&(active.kind==3||active.kind==4)&&p==actor&&ownedBag(p,bag))return true;if(suspension!=null){if(p==actor&&suspendedValid())return true;reset();status="Suspended pose retired; original bag remains in native inventory";}InventoryContainer held=null;int side=-1;for(int n=0;n<2;n++){var item=NativeItems.hand(p,n);if(wearable(item)){if(held!=null){reset();status="Hold one backpack at a time; native inventory remains available";return false;}held=(InventoryContainer)item;side=n;}}if(p!=actor||held!=bag||side!=bagSide){reset();actor=p;bag=held;bagSide=side;}return ownedAt(p,bag,bagSide);}
 private static boolean update(){if(!identify()||!eligible(actor)){pending=active=null;if(!traceEligible(actor)){policy.reset();gesture.reset();}BackpackCapture.clear();return false;}if(!ownedAt(actor,bag,bagSide))return false;long now=System.nanoTime();if(now>=nextScan){try{scan();}catch(IllegalArgumentException invalid){pending=active=null;layout.clear();BackpackCapture.clear();status=invalid.getMessage();return false;}nextScan=now+100_000_000L;}return true;}
 public static synchronized Selection selection(){if(!update())return null;var items=new ArrayList<InventoryItem>();for(int cell=0;cell<8;cell++)items.add(layout.at(page,cell));return new Selection(actor,bag,bagSide,epoch,page,layout.pages(),layout.count(),items,suspension);}
 public static synchronized void page(int direction){if(direction!=1&&direction!=-1)throw new IllegalArgumentException("Backpack page direction");if(!enabled||!Main.ready()||pending!=null||active!=null||!identify()||actor.isDead()||actor.getVehicle()!=null||actor.hasTimedActions()||!Engine.worldPresent||zombie.network.GameClient.client||zombie.network.GameServer.server)return;try{scan();}catch(IllegalArgumentException invalid){status=invalid.getMessage();return;}page=Math.floorMod(page+direction,layout.pages());epoch++;policy.reset();BackpackCapture.clear();status="Backpack page "+(page+1)+"/"+layout.pages();}
 private static int cell(BackpackCapture.View view,ContactFrame.Point point){if(!BackpackCapture.destination(view,point))return -1;var local=BackpackCapture.local(view.basis(),point);int best=-1;double distance=.13;for(int cell=0;cell<8;cell++)if(layout.at(page,cell)==null){var target=BackpackLayout.cell(cell,view.origin());double d=Math.hypot(local.x()-target.x(),local.z()-target.z());if(d<distance){distance=d;best=cell;}}return best;}
 private static boolean itemOwned(InventoryItem item,zombie.inventory.ItemContainer source){return transferable(item)&&item.getContainer()==source&&item.getWorldItem()==null&&source.contains(item);}
 private static BackpackCapture.View view(){var value=BackpackCapture.latest();return BackpackCapture.current(value,System.nanoTime())?value:null;}
 private static boolean recallTarget(BackpackCapture.View view,ContactFrame.Point point){return bagSide<0&&BackpackCapture.bagTouch(view,point,reach)&&BackpackCapture.nearest(view,point,reach/2)==null;}
 public static synchronized boolean preparing(){return bagSide>=0&&pending==null&&active==null&&gesture.preparing(System.nanoTime())&&eligible(actor)&&!prior(bagSide);}
 public static synchronized boolean ownsGrip(int side){if(side<0||side>1||!enabled||!update()||prior(side))return false;if(active!=null&&active.side==side||pending!=null&&pending.side==side)return true;var rig=WorldRigCapture.latest;var contacts=PzvrContacts.sample(System.nanoTime());var h=contacts==null?null:contacts.hand(side);var current=view();if(current==null||h==null||rig==null)return false;if(side==bagSide)return gesture.candidate(rig.hand(side)!=null&&rig.hand(side).trigger(),h.grip(),System.nanoTime())&&BackpackCapture.prepared(actor,bag,epoch,System.nanoTime())!=null;var held=NativeItems.hand(actor,side);return held==null?recallTarget(current,h.centre())||BackpackCapture.nearest(current,h.centre(),reach)!=null:!h.grip()&&held!=bag&&itemOwned(held,actor.getInventory())&&current.held(held)!=null&&BackpackCapture.current(current.held(held).parts())&&bag.getItemContainer().hasRoomFor(actor,held)&&cell(current,h.centre())>=0;}
 public static synchronized boolean ownsTrigger(int side){return bagSide>=0&&side==bagSide&&update()&&pending==null&&active==null&&!prior(side)&&view()!=null;}
 public static String routeTrigger(String key,String original){if(!enabled||!"dominant.trigger".equals(key)&&!"other.trigger".equals(key))return original;return ConsumeRoute.resolve(ownsTrigger(0),ownsTrigger(1),VrApi.dominantHandIndex(),key,original);}
 private static Request make(int kind,int side,InventoryItem item,int cell,List<BackpackCapture.Part> source,BackpackCapture.View view,BackpackCapture.Prepared frozen){return new Request(kind,side,bagSide,actor,bag,item,NativeItems.hand(actor,1-side),++sequence,epoch,WorldRigCapture.latest.generation(),System.nanoTime(),page,cell,item.getID(),item.getFullType(),item.getCount(),item.getCurrentUses(),view.bagParts(),source,frozen);}
 public static synchronized void tick(){
  if(!enabled)return;if(!update()){if(traceEligible(actor)){var contacts=PzvrContacts.sample(System.nanoTime());var rig=WorldRigCapture.latest;if(rig!=null&&rig.actor()==actor&&rig.fresh(System.nanoTime())&&rig.generation()==rigGeneration){for(int side=0;side<2;side++){var h=contacts==null?null:contacts.hand(side);policy.sample(side,h!=null&&h.grip(),side!=bagSide&&h!=null&&rig.hand(side)!=null);}}else policy.reset();}return;}
  long now=System.nanoTime();if(pending!=null&&now-pending.created>250_000_000L){pending=null;policy.reset();gesture.reset();}if(active!=null&&now-active.created>15_000_000_000L){active=null;policy.reset();gesture.reset();}
  var rig=WorldRigCapture.latest;if(rig==null||rig.actor()!=actor||!rig.fresh(now)){policy.reset();gesture.reset();return;}if(rig.generation()!=rigGeneration){rigGeneration=rig.generation();epoch++;pending=active=null;policy.reset();gesture.reset();BackpackCapture.clear();return;}
  var contacts=PzvrContacts.sample(now);var current=view();
  if(bagSide>=0){var h=contacts==null?null:contacts.hand(bagSide);var action=gesture.sample(rig.hand(bagSide)!=null&&rig.hand(bagSide).trigger(),h!=null&&h.grip(),current!=null&&h!=null&&!prior(bagSide)&&pending==null&&active==null,now);if(action==BackpackGesture.Action.PAGE){page(1);return;}if(action==BackpackGesture.Action.SUSPEND){var frozen=BackpackCapture.prepared(actor,bag,epoch,now);if(frozen!=null){pending=make(3,bagSide,bag,-1,frozen.parts(),current,frozen);status="Original bag suspension requested";}else status="Original bag world model unavailable; keep it held or use native inventory";return;}}
  for(int side=0;side<2;side++){var h=contacts==null?null:contacts.hand(side);var edge=policy.sample(side,h!=null&&h.grip(),side!=bagSide&&h!=null&&rig.hand(side)!=null);if(prior(side)||edge==BackpackPolicy.Edge.NONE||pending!=null||active!=null||current==null)continue;
   InventoryItem item;int kind,targetCell=-1;List<BackpackCapture.Part> source;
   if(edge==BackpackPolicy.Edge.PICK&&NativeItems.hand(actor,side)==null){if(recallTarget(current,h.centre())){pending=make(4,side,bag,-1,current.bagParts(),current,suspension);status="Original bag recall requested";break;}var nearest=BackpackCapture.nearest(current,h.centre(),reach);if(nearest==null)continue;item=nearest.item().get();if(!itemOwned(item,bag.getItemContainer()))continue;kind=1;source=nearest.parts();}
   else if(edge==BackpackPolicy.Edge.RETURN){item=NativeItems.hand(actor,side);targetCell=cell(current,h.centre());if(item==bag||!itemOwned(item,actor.getInventory())||targetCell<0||!bag.getItemContainer().hasRoomFor(actor,item)||current.held(item)==null||!BackpackCapture.current(current.held(item).parts()))continue;kind=2;source=current.held(item).parts();}else continue;
   pending=make(kind,side,item,targetCell,source,current,null);status=kind==1?"Native backpack pickup requested":"Native backpack return requested";
  }
 }
 public static synchronized Request request(){return pending;}public static synchronized boolean busy(){return pending!=null||active!=null;}
 public static synchronized boolean valid(IsoPlayer p,InventoryContainer value,InventoryItem item,int side,long ticket,long generation,int phase){
  var r=active!=null?active:pending;long now=System.nanoTime();if(r==null||r.actor!=p||r.bag!=value||r.item!=item||r.side!=side||r.ticket!=ticket||r.epoch!=generation||generation!=epoch||p!=actor||value!=bag||phase<0||phase>2||now<r.created||now-r.created>(active!=null?15_000_000_000L:250_000_000L)||!eligible(p)||!ownedBag(p,value)||NativeItems.hand(p,1-side)!=r.other||r.other!=null&&!supported(r.other)||!BackpackCapture.current(r.bagGeometry)||!BackpackCapture.current(r.itemGeometry)||item.getID()!=r.id||!r.type.equals(item.getFullType())||item.getCount()!=r.count||item.getCurrentUses()!=r.uses||item.getWorldItem()!=null)return false;
  var rig=WorldRigCapture.latest;var contacts=PzvrContacts.sample(now);var h=contacts==null?null:contacts.hand(side);if(rig==null||!rig.fresh(now)||rig.generation()!=r.rigGeneration||h==null||rig.hand(side)==null)return false;
  if(r.kind==3){if(r.frozen==null||!BackpackCapture.current(r.frozen.parts())||h.grip())return false;return phase==0?NativeItems.hand(p,side)==value&&rig.hand(side).trigger()&&context(p,value,r.bagSide,generation):unheld(p,value);}
  if(r.kind==4){if(!h.grip())return false;return phase==2?NativeItems.hand(p,side)==value:unheld(p,value)&&NativeItems.hand(p,side)==null&&suspendedValid()&&BackpackCapture.bagTouch(view(),h.centre(),reach);}
  var current=view();if(current==null||!context(p,value,r.bagSide,generation)||!BackpackCapture.same(current.bagParts(),r.bagGeometry))return false;
  if(r.kind==1){if(!h.grip())return false;var nearest=phase==0?BackpackCapture.nearest(current,h.centre(),reach):null;if(phase==0&&(nearest==null||nearest.item().get()!=item||!BackpackCapture.same(nearest.parts(),r.itemGeometry)))return false;return phase==0?NativeItems.hand(p,side)==null&&itemOwned(item,value.getItemContainer()):phase==1?NativeItems.hand(p,side)==null&&itemOwned(item,p.getInventory()):NativeItems.hand(p,side)==item&&itemOwned(item,p.getInventory());}
  if(r.kind!=2||h.grip()||!BackpackCapture.destination(current,h.centre())||r.page!=page||layout.at(r.page,r.cell)!=null&&layout.at(r.page,r.cell)!=item)return false;
  if(phase==0&&(current.held(item)==null||!BackpackCapture.same(current.held(item).parts(),r.itemGeometry)))return false;
  return phase==0?NativeItems.hand(p,side)==item&&itemOwned(item,p.getInventory()):phase==1?NativeItems.hand(p,side)==null&&itemOwned(item,p.getInventory())&&value.getItemContainer().hasRoomFor(p,item):NativeItems.hand(p,side)==null&&itemOwned(item,value.getItemContainer());
 }
 public static synchronized boolean acknowledge(long ticket,boolean queued){var r=pending;if(r==null||r.ticket!=ticket)return false;if(queued&&!valid(r.actor,r.bag,r.item,r.side,r.ticket,r.epoch,0))return false;pending=null;if(queued){active=r;return true;}policy.reset();gesture.reset();return true;}
 public static synchronized void finished(long ticket,boolean success){var r=active;if(r==null||r.ticket!=ticket)return;boolean committed=success&&valid(r.actor,r.bag,r.item,r.side,r.ticket,r.epoch,2);active=pending=null;policy.reset();gesture.reset();
  if(committed){if(r.kind==3){suspension=r.frozen;bagSide=-1;epoch++;BackpackCapture.clear();status="Original bag suspended; grip its mesh to recall";}else if(r.kind==4){suspension=null;bagSide=r.side;epoch++;BackpackCapture.clear();NativeItems.adoptBody(r.actor,r.item,r.side);status="Original bag recalled to native hand";}else if(r.kind==1){NativeItems.adoptBody(r.actor,r.item,r.side);policy.adopt(r.side,true);status="Original item drawn from backpack";}else{layout.place(r.item,r.page,r.cell);status="Original item returned to backpack";}}
  else status="Backpack action retired; original inventories retained";
 }
 public static synchronized String status(){return status+"; "+BackpackCapture.status();}
 private BackpackContents(){}
}